mapper.select:
SELECT COUNT(*) FROM TB_IF_CAPACITY_PILOT
 WHERE TARGET_TYPE_CD = #{targetTypeCd} AND TARGET_ID = #{targetId}
   AND METRIC_SCOPE_CD = #{metricScopeCd}

mapper.insert:
INSERT INTO TB_IF_CAPACITY_PILOT (
  SNAPSHOT_ID, TARGET_TYPE_CD, TARGET_ID, METRIC_SCOPE_CD, CAPTURED_AT,
  CPU_PCT, MEM_PCT, TPS, RESP_P95_MS, DB_CONN_PEAK, REMARK, REG_USER_ID, REG_DTM
) VALUES (
  #{snapshotId}, #{targetTypeCd}, #{targetId}, #{metricScopeCd}, #{capturedAt},
  #{cpuPct}, #{memPct}, #{tps}, #{respP95Ms}, #{dbConnPeak}, #{remark}, #{regUserId}, #{regDtm}
)

mapper.update:
UPDATE TB_IF_CAPACITY_PILOT
   SET CAPTURED_AT=#{capturedAt}, CPU_PCT=#{cpuPct}, MEM_PCT=#{memPct}, TPS=#{tps},
       RESP_P95_MS=#{respP95Ms}, DB_CONN_PEAK=#{dbConnPeak}, REMARK=#{remark},
       SNAPSHOT_ID=NVL(#{snapshotId}, SNAPSHOT_ID)
 WHERE TARGET_TYPE_CD=#{targetTypeCd} AND TARGET_ID=#{targetId}
   AND METRIC_SCOPE_CD=#{metricScopeCd}
